function abs(x){return new URL(String(x||''),location.href).href;}
function imageRequest(url){return new MR(abs(url),'GET',[new KV('Accept','image/avif,image/webp,image/apng,image/*,*/*;q=0.8')],null);}
function extra(){return new Extra([new Commands('',E)],E);}
function finish(images,error){if(finished)return;finished=true;try{if(exportFrame)exportFrame.remove();}catch(e){}saved().textContent=JSON.stringify(new Chapters(new MR('','',E,null),extra(),new JC(false,false,''),new ChapterOutput(null,images,error||null)));done();}
function challenged(){var node=document.querySelector('.wafcap')||document.querySelector('[aria-label="Security check"]');if(!node)return false;if(node.hidden||node.getAttribute&&node.getAttribute('aria-hidden')==='true')return false;try{var style=getComputedStyle(node);if(style.display==='none'||style.visibility==='hidden')return false;}catch(e){}return true;}
async function waitForChallenge(){for(var attempt=0;attempt<50&&challenged();attempt++)await sleep(100);return !challenged();}

function readerVerification(){
 var target=new URL(location.href),key='zetsu-comix-reader-verify-v2:'+target.pathname;
 if(target.protocol!=='https:'||target.hostname!=='comix.to'||!/^\/title\/[^/]+\/\d+-chapter-[^/]+\/?$/.test(target.pathname))return false;
 try{var last=Number(localStorage.getItem(key)||0);if(Date.now()-last<600000)return false;localStorage.setItem(key,String(Date.now()));}catch(e){return false;}
 var command=new Commands('helperFunction',[new KV('name','comix-reader-verification'),new KV('isCustomRequest','true')]);
 finished=true;
 try{if(exportFrame)exportFrame.remove();}catch(e){}
 saved().textContent=JSON.stringify(new Chapters(new MR(target.href,'GET',[],null),new Extra([command],[new KV('comixReaderVerificationAttempted','true')]),new JC(false,true,''),new ChapterOutput(null,[],null)));done();return true;
}
async function checkReaderVerification(){if(challenged()&&!await waitForChallenge())throw new Error('Human verification is required for this chapter');}

function nodeList(){return Array.prototype.slice.call(document.querySelectorAll('.rpage-page[data-page]'));}
function slot(node){return Number(node.getAttribute('data-page'))-1;}
function source(node){var img=node&&node.querySelector('img.rpage-page__img,img[alt^="Page "]');if(!img)return '';var candidates=[img.getAttribute('src'),img.getAttribute('data-src'),img.currentSrc];for(var i=0;i<candidates.length;i++)try{if(candidates[i]){var parsed=new URL(candidates[i],location.href);if(parsed.protocol==='https:'||parsed.protocol==='http:')return parsed.href;}}catch(e){}return '';}
function collect(urls){nodeList().forEach(function(node){var index=slot(node),url=source(node);if(index>=0&&index<urls.length&&url)urls[index]=url;});}
async function waitImage(index,timeout){for(var n=0;n<timeout/75;n++){await checkReaderVerification();var node=document.querySelector('.rpage-page[data-page="'+(index+1)+'"]');if(source(node))return;await sleep(75);}}

async function loadUrls(){
 var nodes=[];for(var n=0;n<300;n++){await checkReaderVerification();nodes=nodeList();if(nodes.length)break;await sleep(100);}
 if(!nodes.length)throw new Error('Reader page slots missing');
 var count=Math.max.apply(null,nodes.map(function(node){return Number(node.getAttribute('data-page'))||0;}));
 if(count!==nodes.length||count>1000)throw new Error('Invalid reader page slots');
 var urls=new Array(count),started=Date.now();collect(urls);
 for(var index=0;index<count;index++){
  if(urls[index])continue;
  if(Date.now()-started>180000)throw new Error('Reader stopped before all panels loaded');
  var node=document.querySelector('.rpage-page[data-page="'+(index+1)+'"]'),button=document.querySelector('button[aria-label="Go to page '+(index+1)+'"]');
  if(button&&!button.disabled)button.click();else if(node&&node.scrollIntoView)node.scrollIntoView({block:'center'});else throw new Error('Reader page navigation missing for '+(index+1));
  await waitImage(index,8000);collect(urls);
  if(!urls[index])throw new Error('Panel '+(index+1)+' did not load');
 }
 return urls;
}
function makeExportRealm(){var frame=document.createElement('iframe');frame.id='ketsu-export-'+Date.now();frame.src='about:blank';frame.style.cssText='display:none!important;width:0;height:0;border:0';document.documentElement.appendChild(frame);if(!frame.contentDocument||!frame.contentWindow)throw new Error('Clean image canvas unavailable');exportFrame=frame;return {doc:frame.contentDocument,win:frame.contentWindow};}
function wasm(){if(wasmExports)return wasmExports;var raw=atob(DESCRAMBLE_WASM),bytes=new Uint8Array(raw.length);for(var i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);wasmExports=new WebAssembly.Instance(new WebAssembly.Module(bytes)).exports;return wasmExports;}
function tileOrder(seed,count,version){var engine=wasm(),pointer=(version===2?engine.buildOrderV2:engine.buildOrderV1)(seed>>>0,count);return Array.from(new Int32Array(engine.memory.buffer,pointer,count));}
function blobData(blob){return new Promise(function(resolve,reject){var reader=new FileReader;reader.onload=function(){var value=String(reader.result||'');value.indexOf('data:image/')===0?resolve(value):reject(new Error('Image export failed'));};reader.onerror=function(){reject(new Error('Blob read failed'));};reader.readAsDataURL(blob);});}
function exportCanvas(canvas){return new Promise(function(resolve,reject){canvas.toBlob(function(blob){if(!blob)return reject(new Error('Canvas blob failed'));blobData(blob).then(resolve,reject);},'image/jpeg',0.9);});}
function saveNativeImage(data,key){if(finished)return false;try{window.webkit.messageHandlers.SAVE_BASE64_CACHE.postMessage(JSON.stringify({base64String:data,key:key}));return true;}catch(e){return false;}}

async function bitmapFromBlob(blob,realm){
 if(typeof realm.win.createImageBitmap==='function'){
  try{return await realm.win.createImageBitmap(blob,{colorSpaceConversion:'none'});}catch(e){}
 }
 // Older WebKit can decode an image element even when createImageBitmap is unavailable.
 return await new Promise(function(resolve,reject){
  var image=new realm.win.Image(),url=realm.win.URL.createObjectURL(blob),timer;
  function release(){clearTimeout(timer);image.onload=null;image.onerror=null;realm.win.URL.revokeObjectURL(url);}
  image.onload=function(){var width=image.naturalWidth,height=image.naturalHeight;release();if(!width||!height)return reject(new Error('Invalid image dimensions'));resolve(image);};
  image.onerror=function(){release();reject(new Error('This WebView cannot decode the panel image'));};
  timer=setTimeout(function(){release();reject(new Error('Image decoding timed out'));},12000);
  image.src=url;
 });
}

async function decodePage(url,realm){var Controller=realm.win.AbortController||AbortController,controller=new Controller(),timer=setTimeout(function(){controller.abort();},15000),bitmap=null,canvas=null;try{var response=await realm.win.fetch(url,{mode:'cors',credentials:'omit',referrerPolicy:'no-referrer',signal:controller.signal});if(!response.ok)throw new Error('Image request '+response.status);var hash=String(response.headers.get('X-Scramble-Hash')||'').trim(),seedHeader=parseInt(response.headers.get('X-Scramble-Seed')||'0',10)||0;if(hash&&!Object.prototype.hasOwnProperty.call(HASH_MASKS,hash))throw new Error('Unknown image scramble hash '+hash);var seed=(seedHeader^(HASH_MASKS[hash]||0))>>>0,grid=String(response.headers.get('X-Scramble-Grid')||'5x5').split('x'),cols=parseInt(grid[0],10)||5,rows=parseInt(grid[1],10)||5,version=response.headers.get('X-Scramble-Algo')==='3'?2:1,blob=await response.blob();if(!blob.size)throw new Error('Empty image response');if(blob.type&&!/^image\//i.test(blob.type))throw new Error('Image URL returned '+blob.type);bitmap=await bitmapFromBlob(blob,realm);canvas=realm.doc.createElement('canvas');if(!bitmap.width||!bitmap.height)throw new Error('Invalid image dimensions');canvas.width=bitmap.width;canvas.height=bitmap.height;var context=canvas.getContext('2d',{colorSpace:'srgb'});if(!context)throw new Error('Image canvas unavailable');context.drawImage(bitmap,0,0);if(seed){var tileW=Math.floor(bitmap.width/cols),tileH=Math.floor(bitmap.height/rows),count=cols*rows,order=tileOrder(seed,count,version);if(tileW<1||tileH<1)throw new Error('Invalid image tile grid');for(var i=0;i<count;i++){var dest=order[i];context.drawImage(bitmap,(i%cols)*tileW,Math.floor(i/cols)*tileH,tileW,tileH,(dest%cols)*tileW,Math.floor(dest/cols)*tileH,tileW,tileH);}}var data=await exportCanvas(canvas);if(!saveNativeImage(data,url))throw new Error('Native image cache unavailable');return imageRequest(url);}finally{clearTimeout(timer);try{if(bitmap&&bitmap.close)bitmap.close();if(canvas){canvas.width=0;canvas.height=0;}}catch(e){}}}

async function decodeAll(urls){
 var realm=makeExportRealm(),results=new Array(urls.length),cursor=0,stopped=false;
 async function worker(){while(!stopped&&cursor<urls.length){var index=cursor++,timer;try{
  // AbortController does not bound bitmap/canvas/FileReader promises. Bound the whole operation.
  results[index]=await Promise.race([decodePage(urls[index],realm),new Promise(function(resolve,reject){timer=setTimeout(function(){reject(new Error('Image preparation timed out'));},20000);})]);
 }catch(e){stopped=true;throw new Error('page '+(index+1)+': '+String(e.message||e));}finally{clearTimeout(timer);}}}
 var jobs=[];for(var i=0;i<Math.min(2,urls.length);i++)jobs.push(worker());
 try{await Promise.all(jobs);}catch(e){stopped=true;throw new Error('Image preparation failed: '+e.message);}
 await sleep(700);return results;
}
async function run(){try{await checkReaderVerification();var urls=await loadUrls(),images=await decodeAll(urls);finish(images,null);}catch(e){if(challenged()&&readerVerification())return;finish([],'Reader error: '+e.message);}}
setTimeout(run,50);
